import{o as s,c as n,a0 as l,j as e,t as d,p as r}from"./chunks/framework.L_oL6aia.js";const i={class:"rock-card-contact",style:{"margin-top":"2.5rem"}},c={class:"rock-copy-email-wrapper"},m=JSON.parse('{"title":"Tattoo You: ユーザーマニュアル","description":"","frontmatter":{},"headers":[],"relativePath":"ja/tattoo-you.md","filePath":"ja/tattoo-you.md"}'),g={name:"ja/tattoo-you.md"},q=Object.assign(g,{setup(u){const t=r("メールアドレスをコピー");function a(){navigator.clipboard.writeText("mainstaudiolabs@gmail.com"),t.value="コピーしました！",setTimeout(function(){t.value="メールアドレスをコピー"},2e3)}return(p,o)=>(s(),n("div",null,[o[3]||(o[3]=l(`<h1 id="tattoo-you-ユーザーマニュアル" tabindex="-1">Tattoo You: ユーザーマニュアル <a class="header-anchor" href="#tattoo-you-ユーザーマニュアル" aria-label="Permalink to &quot;Tattoo You: ユーザーマニュアル&quot;">​</a></h1><p><strong>バージョン 1.0.0 · バーチャルアンプ・シミュレーション＆ヴィンテージFXスイート</strong></p><img src="/tattoo-you.png" alt="Tattoo You Plugin GUI" style="width:100%;max-width:100%;height:auto;display:block;margin:1.75rem auto;border:2px solid var(--vp-c-border);border-radius:8px;box-shadow:0 8px 24px rgba(0,0,0,0.35);"><blockquote><p><strong>ストーンズ・ファンがギタリストのために捧げるプラグイン：</strong><br><strong>Tattoo You</strong> は、ローリング・ストーンズのギターサウンドを構成するセッションテープ、ライブ音源、そして機材の細部に至るまでを執念深く研究して開発されました。熱狂的なストーンズファンであり熟練のギタリストでもある開発陣が、ギターを繋いでノブを回すだけで、1978–1981年の伝説的トーン――あの唯一無二のタッチレスポンス、パンチ、そしてグルーヴ――に即座に没入できるよう設計しました。</p></blockquote><hr><h2 id="_1-設計思想-1978–1981-真空管-fxの黄金期" tabindex="-1">1. 設計思想：1978–1981 真空管＆FXの黄金期 <a class="header-anchor" href="#_1-設計思想-1978–1981-真空管-fxの黄金期" aria-label="Permalink to &quot;1. 設計思想：1978–1981 真空管＆FXの黄金期&quot;">​</a></h2><p><strong>Tattoo You</strong> は、キース・リチャーズとローリング・ストーンズが1970年代後半から1980年代初頭のスタジオおよびライブステージで確立した決定的なギタートーンを再現します。この時代は、初期の粗削りなAmpegやFenderのクランチから、<strong>6L6真空管を搭載したMesa/Boogie回路</strong>、高耐入力な<strong>Electro-Voice EVM-12L 1x12スピーカー</strong>、そして前段に配置されたアナログモジュレーションエフェクトという、高いヘッドルームと多段ゲイン構成への歴史的な転換期でした。</p><h3 id="歴史的タイムライン-1978–1981" tabindex="-1">歴史的タイムライン：1978–1981 <a class="header-anchor" href="#歴史的タイムライン-1978–1981" aria-label="Permalink to &quot;歴史的タイムライン：1978–1981&quot;">​</a></h3><ol><li><p><strong>パリ・セッション（1978年 · 『<em>Some Girls（女たち）</em>』/『<em>Beast of Burden</em>』）：</strong><br> パリの <em>Pathé Marconi Studios</em> において、キースは自然な真空管クリーンに <strong>Phase &#39;78</strong>（MXR Phase 100 スタイル）のリキッドなオプティカル・モジュレーションと、温かみのあるアナログ・テープエコー（スラップバック）を組み合わせた象徴的なサウンドを確立しました。これは <em>&quot;Beast of Burden&quot;</em>、<em>&quot;Miss You&quot;</em>、<em>&quot;Shattered&quot;</em> などのギターテクスチャーとして不朽の名作に刻まれています。</p></li><li><p><strong>トロピカル・オーバードライブ期（1979–1980年 · 『<em>Emotional Rescue</em>』）：</strong><br> パリとバハマの <em>Compass Point Studios</em> で行われたレコーディングでは、タイトなファンクロックのダイナミクス（<em>&quot;Emotional Rescue&quot;</em>、<em>&quot;Dance Part 1&quot;</em>）、切れ味鋭いレゲエ／スカのカッティング、そしてピッキングの強弱に追従する粘りのあるブルース・リードに対応するため、機材のヘッドルームとタッチレスポンスがさらに洗練されました。</p></li><li><p><strong>名盤のリフ・パワー（1981年 · 『<em>Tattoo You（刺青の男）</em>』）：</strong><br> パリとニューヨークの <em>Atlantic Studios</em> で完成された『<em>Tattoo You</em>』は、このギターリグの頂点を示しています。<em>&quot;Start Me Up&quot;</em> の忘れられないリズムクランチ、<em>&quot;Little T&amp;A&quot;</em> のドライビングなパンチ、<em>&quot;Slave&quot;</em> の粘りあるグルーヴ、そして <em>&quot;Hang Fire&quot;</em> や <em>&quot;Neighbours&quot;</em> の獰猛なロックサウンドは、今なおロックギタートーンの最高峰のリファレンスです。</p></li></ol><p>👉 <a href="/ja/history-mesa-stones.html"><strong>「ストーンズはアンプに金を払わない」：ストーンズがMesa/Boogieを手に入れた歴史的ストーリー（1978–1981） →</strong></a></p><hr><h2 id="_2-デュアル・パワーアンプ構造-head-vs-combo" tabindex="-1">2. デュアル・パワーアンプ構造：HEAD vs COMBO <a class="header-anchor" href="#_2-デュアル・パワーアンプ構造-head-vs-combo" aria-label="Permalink to &quot;2. デュアル・パワーアンプ構造：HEAD vs COMBO&quot;">​</a></h2><p><strong>Tattoo You</strong> は、コントロールパネル下部にパワーアンプの回路トポロジー切り替えスイッチを搭載しています。ステージとスタジオで使い分けられていた2種類の実機構成を切り替え可能です：</p><table tabindex="0"><thead><tr><th style="text-align:left;">パワーアンプ・モード</th><th style="text-align:left;">回路トポロジー</th><th style="text-align:left;">音響特性＆ダイナミクス</th><th style="text-align:left;">最適なサウンド</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>HEAD</code></strong></td><td style="text-align:left;"><strong>100W 6L6 パワーアンプ (Quad 6L6)</strong></td><td style="text-align:left;">圧倒的なダイナミック・ヘッドルーム、タイトで打撃感のある低域、電光石火のトランジェント・レスポンス。パワー段の不要なタレ（サグ）のないアグレッシブなノートアタック。</td><td style="text-align:left;">スタジアム級のロックリフ（<em>&quot;Start Me Up&quot;</em>, <em>&quot;Little T&amp;A&quot;</em>, <em>&quot;Hang Fire&quot;</em>）、重厚なコードバッキング、高インパクトなリズムトラッキング。</td></tr><tr><td style="text-align:left;"><strong><code>COMBO</code></strong></td><td style="text-align:left;"><strong>60W 6L6 パワーアンプ (Dual 6L6)</strong></td><td style="text-align:left;">有機的な電源サグ、ナチュラルなパワー管コンプレッション、芳醇な中域倍音。ピッキングを強く押し込んだ際の吸い付くようなバイト感と粘り。</td><td style="text-align:left;">ダイナミックなソウル・クリーン（<em>&quot;Beast of Burden&quot;</em>, <em>&quot;Tops&quot;</em>）、歌うようなブルース・リード、ファンク・カッティング（<em>&quot;Dance Part 1&quot;</em>）、親密なスタジオトラック（<em>&quot;Waiting on a Friend&quot;</em>）。</td></tr></tbody></table><ul><li><strong>インタラクティブな切り替え:</strong> トグルスイッチを操作するか、<code>HEAD</code> / <code>COMBO</code> のテキストラベルを直接クリックすることでも切り替えられます。</li></ul><hr><h2 id="_3-3チャンネル・ニューラルアンプ構成" tabindex="-1">3. 3チャンネル・ニューラルアンプ構成 <a class="header-anchor" href="#_3-3チャンネル・ニューラルアンプ構成" aria-label="Permalink to &quot;3. 3チャンネル・ニューラルアンプ構成&quot;">​</a></h2><p>3ポジションのロータリーセレクターにより、ヴィンテージ6L6回路のゲインレンジを網羅します：</p><table tabindex="0"><thead><tr><th style="text-align:left;">チャンネル</th><th style="text-align:left;">トーンキャラクター</th><th style="text-align:left;">最適な用途</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>CLEAN</code></strong></td><td style="text-align:left;">自然な真空管コンプレッション、広いヘッドルーム、そして艶やかな高域を持つリッチなクリーントーン。</td><td style="text-align:left;">リズムコードの分離感（<em>&quot;Beast of Burden&quot;</em>, <em>&quot;Tops&quot;</em>）、ファンク・カッティング、ソウル・バラード。</td></tr><tr><td style="text-align:left;"><strong><code>CRUNCH</code></strong></td><td style="text-align:left;">太いボディ感、パンチのある中域、そしてピッキングのタッチに即座に反応する、歪み始め（Edge-of-breakup）のトーン。</td><td style="text-align:left;">伝説のクラシック・ロックリフ（<em>&quot;Start Me Up&quot;</em>, <em>&quot;Little T&amp;A&quot;</em>, <em>&quot;Hang Fire&quot;</em>）、コードクランチ、ブルースリズム。</td></tr><tr><td style="text-align:left;"><strong><code>LEAD</code></strong></td><td style="text-align:left;">芳醇な倍音サステイン、滑らかなソロの弾き心地、そして引き締まった低域を持つハイゲイン・サチュレーション。</td><td style="text-align:left;">伸びやかなリードギター、ヘヴィなリフ、スライドギター（<em>&quot;Slave&quot;</em>, <em>&quot;Neighbours&quot;</em>）。</td></tr></tbody></table><hr><h2 id="_4-シグナルフロー-コントロール・ガイド" tabindex="-1">4. シグナルフロー＆コントロール・ガイド <a class="header-anchor" href="#_4-シグナルフロー-コントロール・ガイド" aria-label="Permalink to &quot;4. シグナルフロー＆コントロール・ガイド&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ ギター入力 ]</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span> [ 適応型ノイズゲート (-58 dB) ]</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span> [ PHASE &#39;78 ]  ───►  [ SLAPBACK DELAY ]</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span> [ 入力ゲイン・ドライブ ]</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span> [ アナログ・ソフトクリッパー (-0.1 dBFS) ]</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span> [ 6L6 ニューラルプリアンプ (Clean / Crunch / Lead) ]</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span> [ パワーアンプ・トポロジー (Head 100W / Combo 60W) ]</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span> [ 5バンド・グラフィックEQ ]  ───►  [ 「MICK」EVM-12L キャビネット ]</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span> [ マスター出力 ]  ───►  [ ステレオ出力 ]</span></span></code></pre></div><h3 id="_1-入力段-ダイナミック保護" tabindex="-1">1. 入力段＆ダイナミック保護 <a class="header-anchor" href="#_1-入力段-ダイナミック保護" aria-label="Permalink to &quot;1. 入力段＆ダイナミック保護&quot;">​</a></h3><ul><li><strong><code>ADAPTIVE NOISE GATE</code>:</strong> 入力直後に配置され、ギター演奏の長い自然なサステインを損なうことなく、50/60Hzの電磁ハムノイズやハイゲイン時のヒスノイズを自動除去します（アタック 1.5ms、ホールド 35ms、ナチュラルリリース 140ms）。</li><li><strong><code>ANALOG WAVESHAPER / SOFT CLIPPER (-0.1 dBFS)</code>:</strong> NAMニューラルエンジンの直前に配置された双曲線正接（tanh）サチュレーション。通常の演奏では100%リニアな透明性を保ちつつ、突発的なピークによるデジタルクリップを音楽的に保護します。</li></ul><h3 id="_2-メインアンプ・コントロール" tabindex="-1">2. メインアンプ・コントロール <a class="header-anchor" href="#_2-メインアンプ・コントロール" aria-label="Permalink to &quot;2. メインアンプ・コントロール&quot;">​</a></h3><ul><li><strong><code>GAIN</code> (Volume / Drive):</strong> アンプに入力されるシグナルドライブ量を設定します（<code>1.0</code> = -9 dB, <code>7.0</code> = 0 dB ユニティゲイン, <code>10.0</code> = +4.5 dB ブースト）。</li><li><strong><code>VOLUME</code> (Master):</strong> 出力マスターボリューム（<code>1.0</code> = -36 dB の小音量, <code>7.0</code> = 0 dB ユニティゲイン, <code>10.0</code> = +18 dB ブースト）。</li><li><strong><code>HEAD / COMBO SWITCH</code>:</strong> 100W Quad-6L6 Head と 60W Dual-6L6 Combo のパワー回路トポロジーを切り替えます。</li><li><strong><code>CHANNEL SELECTOR</code>:</strong> <code>CLEAN</code>、<code>CRUNCH</code>、<code>LEAD</code> の3チャンネルを選択。</li><li><strong><code>STANDBY</code>:</strong> ギターの持ち替えや曲間のための即時ミュートトグル。</li></ul><h3 id="_3-5バンド・グラフィック・イコライザー" tabindex="-1">3. 5バンド・グラフィック・イコライザー <a class="header-anchor" href="#_3-5バンド・グラフィック・イコライザー" aria-label="Permalink to &quot;3. 5バンド・グラフィック・イコライザー&quot;">​</a></h3><p>独立した <strong><code>EQ IN</code></strong> トグルスイッチとステータスLEDを備えた、アクティブ・スライダーEQの精密な再現です：</p><ul><li><strong><code>80 Hz</code> (±12 dB):</strong> 重低音の打撃感とキャビネットの箱鳴り感を調整。</li><li><strong><code>240 Hz</code> (±12 dB):</strong> ローミッドの濁り（ボックス感）をコントロール。カットすることでクリアさが増します。</li><li><strong><code>750 Hz</code> (±12 dB):</strong> 中音域のパンチとバイト感を決定づける帯域。</li><li><strong><code>2200 Hz / 2.2 kHz</code> (±12 dB):</strong> アタック周波数！ ピックのアタック音とコードのエッジを生み出します。</li><li><strong><code>6600 Hz / 6.6 kHz</code> (±12 dB):</strong> EVM-12Lスピーカー特有の開放的なプレゼンスと空気感を付加。</li></ul><h3 id="_4-stones-78-ヴィンテージ・デュアルfxスイート" tabindex="-1">4. Stones &#39;78 ヴィンテージ・デュアルFXスイート <a class="header-anchor" href="#_4-stones-78-ヴィンテージ・デュアルfxスイート" aria-label="Permalink to &quot;4. Stones &#39;78 ヴィンテージ・デュアルFXスイート&quot;">​</a></h3><p>実機ペダルボードと同様に、プリアンプの直前段に直結されています：</p><h4 id="phase-78-mxr-phase-100-スタイル・オプティカル・フェイザー" tabindex="-1"><strong>Phase &#39;78 (MXR Phase 100 スタイル・オプティカル・フェイザー)</strong> <a class="header-anchor" href="#phase-78-mxr-phase-100-スタイル・オプティカル・フェイザー" aria-label="Permalink to &quot;**Phase &#39;78 (MXR Phase 100 スタイル・オプティカル・フェイザー)**&quot;">​</a></h4><p><em>「Beast of Burden」「Shattered」「Slave」で聴かれる象徴的なモジュレーション。リチャーズとロニーのツインギターアンサンブルの中でも埋もれない、太く立体的なうねりを生み出します。</em></p><ul><li><strong><code>PHASE &#39;78 スイッチ＆アンバーLED</code>:</strong> フェイザーのON/OFFを切り替えます（バイパス時はCPU 0%）。</li><li><strong><code>SPEED</code> (<code>0.10 Hz</code> 〜 <code>8.00 Hz</code>):</strong> モジュレーション周期を数値表示付きで精密調整。</li><li><strong><code>INTENS</code> (<code>0%</code> 〜 <code>100%</code>):</strong> スイープの深さとレゾナンスの深さをコントロール。</li></ul><h4 id="slapback-delay-アナログ・テープエコー" tabindex="-1"><strong>Slapback Delay (アナログ・テープエコー)</strong> <a class="header-anchor" href="#slapback-delay-アナログ・テープエコー" aria-label="Permalink to &quot;**Slapback Delay (アナログ・テープエコー)**&quot;">​</a></h4><p><em>名盤で多用された110ms付近のスイートスポットを再現した温かみのあるアナログ・テープディレイ。</em></p><ul><li><strong><code>DELAY スイッチ＆レッドLED</code>:</strong> テープエコーのON/OFFを切り替えます。</li><li><strong><code>TIME</code> (<code>20 ms</code> 〜 <code>300 ms</code>):</strong> ディレイタイムを設定（デフォルトはキースの定番である <code>110 ms</code>）。</li><li><strong><code>REPEATS</code> (<code>0%</code> 〜 <code>65%</code>):</strong> テープフィードバック量を調整。</li><li><strong><code>MIX</code> (<code>0%</code> 〜 <code>50%</code>):</strong> エフェクト音の混ざり具合を調整。</li></ul><h3 id="_5-「mick」キャビネット・モジュール-1x12-evm-12l" tabindex="-1">5. 「MICK」キャビネット・モジュール (1x12 EVM-12L) <a class="header-anchor" href="#_5-「mick」キャビネット・モジュール-1x12-evm-12l" aria-label="Permalink to &quot;5. 「MICK」キャビネット・モジュール (1x12 EVM-12L)&quot;">​</a></h3><p>実機の Electro-Voice EVM-12L (200W) を搭載した 1x12 ポート付きキャビネットと、位相が完全に揃えられた7種類のスタジオマイク配置を、左右の矢印ボタン（<code>&lt;</code> と <code>&gt;</code>）またはテキストクリックでスムーズに切り替えられます：</p><ol><li><strong><code>SM57 SweetSpot</code>:</strong> Shure SM57 をキャップエッジに配置。バランスの良いアタック、太い中域、ソリッドなパンチ。</li><li><strong><code>SM57 Warm</code>:</strong> Shure SM57 をアウターコーンに配置。豊かな低域と滑らかな高域を持つ温かみのあるトーン。</li><li><strong><code>SM57 Direct</code>:</strong> Shure SM57 をコーン中心に直射。切れ味鋭い輪郭とアタック感。</li><li><strong><code>SM57 BassPort</code>:</strong> Shure SM57 をフロントポートに配置。80–100 Hz の豊かな低域の鳴りを強調。</li><li><strong><code>U87 Studio</code>:</strong> Neumann U87Ai ラージダイアフラム・コンデンサーマイク。高い解像度、ワイドなレンジ、立体的な空気感。</li><li><strong><code>U87 Warm</code>:</strong> Neumann U87Ai をウォームゾーンに配置。耳に痛くない高域と濃密な中低域。</li><li><strong><code>Bypass IR</code>:</strong> 内部キャビネットシミュレーションを無効化し、お好みのサードパーティ製IRローダーと組み合わせ可能。</li></ol><hr><h2 id="_5-内蔵スタジオ・ラックチューナー" tabindex="-1">5. 内蔵スタジオ・ラックチューナー <a class="header-anchor" href="#_5-内蔵スタジオ・ラックチューナー" aria-label="Permalink to &quot;5. 内蔵スタジオ・ラックチューナー&quot;">​</a></h2><img src="/tattoo-you-tuner.png" alt="Tattoo You Integrated Studio Tuner" style="max-width:320px;width:100%;height:auto;display:block;margin:1.5rem auto;border:2px solid var(--vp-c-border);border-radius:8px;box-shadow:0 6px 18px rgba(0,0,0,0.30);"><p>右下の <strong><code>TUNER</code></strong> ボタンをクリックすると、アンプ上にフローティング・スタジオチューナーが表示されます：</p><ul><li><strong>高精度アナログVUメーター:</strong> ±50セントの振れ幅を持ち、チューニングが合うと中央が鮮やかなグリーン（±3セント）に点灯。</li><li><strong>デジタルディスプレイ:</strong> 音名、オクターブ、検出周波数（Hz）、セント偏差をクリアに表示。</li><li><strong>デュアルアルゴリズム (<code>MPM</code> / <code>YIN</code>):</strong> 高速なギタートラッキング（MPM）と低音域・ベースの精密測定（YIN）に対応。</li><li><strong>MUTE機能:</strong> ステージ上での無音チューニングが可能。</li><li><strong>A4基準ピッチ調整:</strong> 432 Hz 〜 448 Hz（ダブルクリックで 440 Hz に即座にリセット）。</li><li><strong>完全CPU 0.0%休止:</strong> <code>CLOSE TUNER</code> ボタンを押すか、背面の暗転したアンプ部分をクリックするだけで即座に閉じ、解析処理を完全停止します。</li></ul><hr><h2 id="_6-おすすめトラックプリセット-セッティング例" tabindex="-1">6. おすすめトラックプリセット＆セッティング例 <a class="header-anchor" href="#_6-おすすめトラックプリセット-セッティング例" aria-label="Permalink to &quot;6. おすすめトラックプリセット＆セッティング例&quot;">​</a></h2><h3 id="プリセット-1-start-me-up-tattoo-you-crunch-王道リフ・パワー" tabindex="-1">プリセット 1: &quot;Start Me Up&quot; / &quot;Tattoo You Crunch&quot; (王道リフ・パワー) <a class="header-anchor" href="#プリセット-1-start-me-up-tattoo-you-crunch-王道リフ・パワー" aria-label="Permalink to &quot;プリセット 1: &quot;Start Me Up&quot; / &quot;Tattoo You Crunch&quot; (王道リフ・パワー)&quot;">​</a></h3><ul><li><strong>Power Amp:</strong> <code>HEAD</code> (100W)</li><li><strong>Channel:</strong> <code>CRUNCH</code></li><li><strong>Gain:</strong> <code>7.5</code> | <strong>Volume:</strong> <code>7.5</code></li><li><strong>5-Band Graphic EQ:</strong> <code>80Hz: +1.5dB</code> | <code>240Hz: -3.0dB</code> | <code>750Hz: +2.5dB</code> | <code>2.2kHz: +4.0dB</code> | <code>6.6kHz: +2.0dB</code></li><li><strong>Phase &#39;78:</strong> <code>OFF</code></li><li><strong>Slapback Delay:</strong> <code>OFF</code> (または Mix <code>12%</code> でわずかに部屋鳴り感を付加)</li><li><strong>MICK:</strong> <code>SM57 Warm</code> (または <code>SM57 SweetSpot</code>)</li></ul><h3 id="プリセット-2-beast-of-burden-shattered-オプティカル・フェイズ・クリーン" tabindex="-1">プリセット 2: &quot;Beast of Burden&quot; / &quot;Shattered&quot; (オプティカル・フェイズ・クリーン) <a class="header-anchor" href="#プリセット-2-beast-of-burden-shattered-オプティカル・フェイズ・クリーン" aria-label="Permalink to &quot;プリセット 2: &quot;Beast of Burden&quot; / &quot;Shattered&quot; (オプティカル・フェイズ・クリーン)&quot;">​</a></h3><ul><li><strong>Power Amp:</strong> <code>COMBO</code> (60W)</li><li><strong>Channel:</strong> <code>CLEAN</code></li><li><strong>Gain:</strong> <code>7.0</code> | <strong>Volume:</strong> <code>7.0</code></li><li><strong>5-Band Graphic EQ:</strong> <code>80Hz: 0dB</code> | <code>240Hz: -2.0dB</code> | <code>750Hz: +2.0dB</code> | <code>2.2kHz: +3.0dB</code> | <code>6.6kHz: +1.5dB</code></li><li><strong>Phase &#39;78:</strong> <code>ON</code> | Speed: <code>0.80 Hz</code> | Intensity: <code>60%</code></li><li><strong>Slapback Delay:</strong> <code>ON</code> | Time: <code>110 ms</code> | Repeats: <code>20%</code> | Mix: <code>25%</code></li><li><strong>MICK:</strong> <code>SM57 SweetSpot</code> (または <code>U87 Studio</code>)</li></ul><h3 id="プリセット-3-emotional-rescue-dance-part-1-ファンクロック-タイトグルーヴ" tabindex="-1">プリセット 3: &quot;Emotional Rescue&quot; / &quot;Dance Part 1&quot; (ファンクロック＆タイトグルーヴ) <a class="header-anchor" href="#プリセット-3-emotional-rescue-dance-part-1-ファンクロック-タイトグルーヴ" aria-label="Permalink to &quot;プリセット 3: &quot;Emotional Rescue&quot; / &quot;Dance Part 1&quot; (ファンクロック＆タイトグルーヴ)&quot;">​</a></h3><ul><li><strong>Power Amp:</strong> <code>COMBO</code> (60W)</li><li><strong>Channel:</strong> <code>CLEAN</code></li><li><strong>Gain:</strong> <code>6.5</code> | <strong>Volume:</strong> <code>8.0</code></li><li><strong>5-Band Graphic EQ:</strong> <code>80Hz: -1.0dB</code> | <code>240Hz: -4.0dB</code> | <code>750Hz: +1.0dB</code> | <code>2.2kHz: +3.5dB</code> | <code>6.6kHz: +3.0dB</code></li><li><strong>Phase &#39;78:</strong> <code>ON</code> | Speed: <code>1.20 Hz</code> | Intensity: <code>40%</code></li><li><strong>Slapback Delay:</strong> <code>OFF</code></li><li><strong>MICK:</strong> <code>SM57 Direct</code></li></ul><h3 id="プリセット-4-slave-neighbours-歌うようなチューブ・リード-ソロ" tabindex="-1">プリセット 4: &quot;Slave&quot; / &quot;Neighbours&quot; (歌うようなチューブ・リード＆ソロ) <a class="header-anchor" href="#プリセット-4-slave-neighbours-歌うようなチューブ・リード-ソロ" aria-label="Permalink to &quot;プリセット 4: &quot;Slave&quot; / &quot;Neighbours&quot; (歌うようなチューブ・リード＆ソロ)&quot;">​</a></h3><ul><li><strong>Power Amp:</strong> <code>HEAD</code> (100W)</li><li><strong>Channel:</strong> <code>LEAD</code></li><li><strong>Gain:</strong> <code>8.0</code> | <strong>Volume:</strong> <code>7.0</code></li><li><strong>5-Band Graphic EQ:</strong> <code>80Hz: +2.0dB</code> | <code>240Hz: -1.5dB</code> | <code>750Hz: +3.5dB</code> | <code>2.2kHz: +3.0dB</code> | <code>6.6kHz: +2.0dB</code></li><li><strong>Slapback Delay:</strong> <code>ON</code> | Time: <code>140 ms</code> | Repeats: <code>30%</code> | Mix: <code>25%</code></li><li><strong>MICK:</strong> <code>SM57 Direct</code> (または <code>U87 Studio</code>)</li></ul><hr><h2 id="_7-技術仕様-対応環境" tabindex="-1">7. 技術仕様＆対応環境 <a class="header-anchor" href="#_7-技術仕様-対応環境" aria-label="Permalink to &quot;7. 技術仕様＆対応環境&quot;">​</a></h2><ul><li><strong>プラグインフォーマット:</strong> VST3 (64-bit), Standalone アプリケーション (.exe)。</li><li><strong>対応OS:</strong><ul><li><strong>Windows:</strong> Windows 10 / Windows 11 (x64) — <em>現在利用可能</em>。</li><li><strong>macOS:</strong> Universal Binary (Apple Silicon M1/M2/M3/M4 &amp; Intel x64) / AU, VST3, Standalone — <em>近日公開</em>。</li><li><strong>Linux:</strong> Ubuntu / Debian / Arch (VST3, Standalone) — <em>近日公開</em>。</li></ul></li><li><strong>プロセッシングエンジン:</strong> Neural Amp Modeler (NAM) WaveNet アーキテクチャ + 高速リアルタイム畳み込みDSP。</li><li><strong>内部オーディオ解像度:</strong> 64-bit 浮動小数点倍精度処理。</li><li><strong>対応サンプルレート:</strong> 44.1 kHz, 48 kHz, 88.2 kHz, 96 kHz, 176.4 kHz, 192 kHz。</li><li><strong>レイテンシー:</strong> ゼロレイテンシー（0 samples）によるリアルタイムトラッキング対応。</li></ul><hr>`,59)),e("div",i,[o[1]||(o[1]=e("div",{class:"rock-card-contact-title"},"ご質問・フィードバック・音源の共有",-1)),o[2]||(o[2]=e("p",{class:"rock-card-contact-desc"},"Tattoo You はギタリストがギタリストのために開発したプラグインです。ご質問、ご感想、Tattoo You で作った音源の共有などはお気軽にお寄せください：",-1)),e("div",c,[o[0]||(o[0]=e("span",{class:"rock-email-text"},"mainstaudiolabs@gmail.com",-1)),e("button",{class:"rock-copy-btn",onClick:a},d(t.value),1)])])]))}});export{m as __pageData,q as default};
